DROP VIEW PS_EOCC_RECKEYS_VW
/
CREATE VIEW PS_EOCC_RECKEYS_VW (RECNAME, FIELDNAME, FLDSEQNO) AS
 SELECT RECNAME   ,FIELDNAME   ,FIELDNUM   FROM PSRECFIELDDB   WHERE
 ((ROUND(((USEEDIT) / (2)),0) ) * ( 2)) <> USEEDIT
/